// Prints the run sheet for one release candidate: every Manual or Device spec
// in docs/ui-test-suite, one table per area.
//   node scripts/run-sheet.mjs > docs/ui-test-suite/run-sheets/TEMPLATE.md
import { readdirSync, readFileSync } from 'node:fs';

const DIR = 'docs/ui-test-suite';
const out = [];
out.push(
  '# Run sheet (template)',
  '',
  'Generated by `node scripts/run-sheet.mjs`; do not edit by hand. Copy to `run-sheets/<date>-<build>.md`, fill in, and commit with the results.',
  '',
  '| | |',
  '| --- | --- |',
  '| Build and update id | |',
  '| Environment | |',
  '| Devices | |',
  '| Date | |',
  '| Tester | |',
  '',
  'Result: pass, fail or n.a. Put the reason for any fail or n.a. in Notes.',
  '',
);
for (const f of readdirSync(DIR).filter((n) => /^\d.*\.md$/.test(n)).sort()) {
  const lines = readFileSync(`${DIR}/${f}`, 'utf8').replace(/```[\s\S]*?```/g, (m) => m.replace(/[^\n]/g, '')).split('\n');
  const area = /^# (.+)$/m.exec(lines.join('\n'))?.[1] ?? f;
  const rows = [];
  lines.forEach((line, i) => {
    const h = /^### ([A-Z0-9]+-\d+) (.+)$/.exec(line);
    if (!h || h[2].includes('(retired)')) return;
    const meta = lines.slice(i + 1, i + 4).find((l) => /Run:/.test(l)) ?? '';
    if (!/Run: (Manual|Device)/.test(meta)) return;
    const platforms = /Platforms: (.*?) · Run:/.exec(meta)?.[1] ?? '';
    rows.push(`| ${h[1]} | ${h[2].replace(/\|/g, '/')} | ${platforms} | | |`);
  });
  if (!rows.length) continue;
  out.push(`## ${area}`, '', '| ID | Title | Platforms | Result | Notes |', '| --- | --- | --- | --- | --- |', ...rows, '');
}
process.stdout.write(out.join('\n'));
